#include "native/providers/gdn/sm121_q1_math.h"
#include "native/providers/gdn/sm121_silu_table.h"
#include <algorithm>
#include <fstream>
#include <iostream>
#include <stdexcept>
#include <type_traits>
#include <vector>

struct Coordinate { unsigned x; } blockIdx{},blockDim{},threadIdx{};
#define __device__
#define __global__
// The driver extracts this exact kernel body from the c268 source. Only its
// execution qualifiers and one-dimensional coordinates are mocked on the CPU.
#include "step124_convolution_kernel_r1.h"
#undef __global__
#undef __device__

using namespace qrt_sm121_q1;
template<class T> std::vector<T> read(const char* path) {
    std::ifstream f(path,std::ios::binary|std::ios::ate);
    if(!f || f.tellg()<=0 || size_t(f.tellg())>(2u<<20) || size_t(f.tellg())%sizeof(T))
        throw std::runtime_error("extent");
    std::vector<T> result(size_t(f.tellg())/sizeof(T));f.seekg(0);
    f.read(reinterpret_cast<char*>(result.data()),result.size()*sizeof(T));
    if(!f)throw std::runtime_error("read");return result;
}
template<class T> void write(const std::string& path,const std::vector<T>& value) {
    std::ofstream f(path,std::ios::binary);
    f.write(reinterpret_cast<const char*>(value.data()),value.size()*sizeof(T));
    if(!f)throw std::runtime_error("write");
}
template<class T> T element(uint16_t bits) {
    if constexpr(std::is_same<T,uint16_t>::value)return bits;
    else return widen(bits);
}
template<class T> uint16_t encoded(T value) {
    if constexpr(std::is_same<T,uint16_t>::value)return value;
    else return bf16(value);
}
template<class T> void replay(const std::vector<uint16_t>& current_b,const std::vector<uint16_t>& before,
    const std::vector<uint16_t>& after,const std::vector<uint16_t>& weights,
    const std::vector<uint16_t>& expected,const std::vector<unsigned char>& silu,
    size_t position,const std::string& prefix) {
    constexpr unsigned guard=16u;
    const T sentinel=element<T>(0x4a35u);
    const float output_sentinel=widen(0x4a51u);
    std::vector<T> ring(32768u+2u*guard,sentinel);
    std::vector<float> current(8192u),output(8192u+2u*guard,output_sentinel);
    for(unsigned feature=0;feature<8192u;++feature) {
        current[feature]=widen(current_b[feature]);
        for(unsigned tap=0;tap<3u;++tap)
            ring[guard+((position-3u+tap)%4u)*8192u+feature]=element<T>(before[feature*4u+tap]);
    }
    const auto original_ring=ring;
    blockDim.x=256u;
    // Include a complete out-of-range block to verify the kernel's bound.
    for(blockIdx.x=0u;blockIdx.x<33u;++blockIdx.x)
        for(threadIdx.x=0u;threadIdx.x<256u;++threadIdx.x)
            convolution<T>(current.data(),ring.data()+guard,weights.data(),output.data()+guard,position,silu.data());
    size_t output_bad=0,carrier_bad=0,history_bad=0,first=8192u;
    std::vector<uint16_t> actual_output(8192u),actual_history(before);
    for(unsigned feature=0u;feature<8192u;++feature) {
        actual_output[feature]=bf16(output[guard+feature]);
        if(!std::isfinite(output[guard+feature]))throw std::runtime_error("nonfinite output");
        if(actual_output[feature]!=expected[feature]) { ++output_bad;first=std::min(first,size_t(feature)); }
        carrier_bad += qrt_sm121_exp2::bits(output[guard+feature])!=(uint32_t(expected[feature])<<16u);
        for(unsigned tap=0u;tap<3u;++tap) {
            actual_history[feature*4u+tap]=encoded(ring[guard+((position-2u+tap)%4u)*8192u+feature]);
            history_bad += actual_history[feature*4u+tap]!=after[feature*4u+tap];
        }
        // The fourth reference column is padding; it is never an operand.
        if(before[feature*4u+3u]!=after[feature*4u+3u])throw std::runtime_error("reference padding changed");
        for(unsigned slot=0u;slot<4u;++slot)
            if(slot!=position%4u && ring[guard+slot*8192u+feature]!=original_ring[guard+slot*8192u+feature])
                throw std::runtime_error("unowned ring slot modified");
        if(current[feature]!=widen(current_b[feature]))throw std::runtime_error("current mutated");
    }
    for(unsigned i=0u;i<guard;++i)
        if(ring[i]!=sentinel || ring[guard+32768u+i]!=sentinel || output[i]!=output_sentinel ||
            output[guard+8192u+i]!=output_sentinel)throw std::runtime_error("guard changed");
    const std::string storage=std::is_same<T,uint16_t>::value?"bf16":"f32";
    write(prefix+"."+storage+".output.bf16.bin",actual_output);
    write(prefix+"."+storage+".history.bf16.bin",actual_history);
    std::cout<<"{\"ring_storage\":\""<<storage<<"\",\"output_bf16_mismatches\":"<<output_bad
        <<",\"output_f32_carrier_bit_mismatches\":"<<carrier_bad<<",\"active_history_bf16_mismatches\":"<<history_bad
        <<",\"active_history_cells\":24576,\"output_cells\":8192,\"first_output_difference\":";
    if(output_bad)std::cout<<"{\"index\":"<<first<<",\"actual\":"<<actual_output[first]<<",\"expected\":"<<expected[first]<<'}';
    else std::cout<<"null";
    std::cout<<",\"reference_padding_unchanged\":true,\"current_input_immutable\":true,\"unowned_ring_slots_immutable\":true,\"guards_pass\":true,\"out_of_range_block_checked\":true}";
}
int main(int argc,char** argv)try {
    if(argc!=9)throw std::runtime_error("qkv before after weights silu output position output-prefix");
    const auto current=read<uint16_t>(argv[1]),before=read<uint16_t>(argv[2]),after=read<uint16_t>(argv[3]);
    const auto weights=read<uint16_t>(argv[4]),expected=read<uint16_t>(argv[6]);
    const auto silu=read<unsigned char>(argv[5]);const size_t position=std::stoull(argv[7]);
    if(current.size()!=8192u || expected.size()!=8192u || before.size()!=32768u || after.size()!=32768u ||
        weights.size()!=32768u || position<3u || !qrt_sm121_silu::valid_layout(silu.data(),silu.size()))
        throw std::runtime_error("shape/layout");
    std::cout<<"{\"layouts\":[";
    replay<uint16_t>(current,before,after,weights,expected,silu,position,argv[8]);std::cout<<',';
    replay<float>(current,before,after,weights,expected,silu,position,argv[8]);std::cout<<"]}\n";
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 2;}
